import{_ as e,o,c as t,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_4.md"}'),i={name:"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_4.md"};function r(s,a,l,d,c,u){return o(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-redes-trayecto-ii" tabindex="-1">Materia: Redes (Trayecto II) <a class="header-anchor" href="#materia-redes-trayecto-ii" aria-label="Permalink to &quot;Materia: Redes (Trayecto II)&quot;">​</a></h2><h3 id="eje-tematico-tecnologias-lan-y-ancho-de-banda" tabindex="-1">Eje Temático: Tecnologías LAN y Ancho de Banda <a class="header-anchor" href="#eje-tematico-tecnologias-lan-y-ancho-de-banda" aria-label="Permalink to &quot;Eje Temático: Tecnologías LAN y Ancho de Banda&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-ley-de-la-autopista" tabindex="-1">🧭 Introducción: La Ley de la Autopista <a class="header-anchor" href="#🧭-introduccion-la-ley-de-la-autopista" aria-label="Permalink to &quot;🧭 Introducción: La Ley de la Autopista&quot;">​</a></h2><p>Imagina que te encargas del transporte de Caracas. Construyes la autopista más moderna y ancha del continente (Un excelente cable de fibra óptica o un switch de alta gama). Sin embargo, si al final de la autopista hay un túnel donde solo cabe un carro a la vez, se formará un atasco gigantesco. Toda tu costosa autopista se volverá inútil debido a ese &quot;Cuello de Botella&quot;.</p><p>En las redes pasa exactamente lo mismo. No importa qué tan rápido es el procesador de tu computadora; si el canal de la red es estrecho, el archivo tardará horas en descargarse. Esta evaluación cierra el trimestre estudiando las medidas de capacidad y la tecnología reina que logró democratizar la velocidad en las redes locales.</p><hr><h2 id="🏛️-capitulo-i-el-ancho-de-banda-y-la-velocidad-de-red" tabindex="-1">🏛️ CAPÍTULO I: El Ancho de Banda y la Velocidad de Red <a class="header-anchor" href="#🏛️-capitulo-i-el-ancho-de-banda-y-la-velocidad-de-red" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Ancho de Banda y la Velocidad de Red&quot;">​</a></h2><p>En el lenguaje coloquial solemos decir &quot;Tengo 100 Megas de Internet&quot;. Pero como ingenieros, debemos dominar la terminología exacta, porque existe una confusión matemática masiva provocada intencionalmente por los equipos de marketing de las empresas proveedoras de internet (ISPs).</p><h3 id="_1-1-ancho-de-banda-bandwidth" tabindex="-1">1.1 Ancho de Banda (Bandwidth) <a class="header-anchor" href="#_1-1-ancho-de-banda-bandwidth" aria-label="Permalink to &quot;1.1 Ancho de Banda (Bandwidth)&quot;">​</a></h3><p>Técnicamente, el Ancho de Banda mide la <strong>Capacidad teórica máxima</strong> de un medio de transmisión. Es &quot;el ancho de la tubería de agua&quot;. Se mide en <strong>Bits por Segundo (bps)</strong>. <em>Recuerda la base matemática: Un Bit es un cero o un uno (<code>b</code> minúscula). Un Byte (Octeto) son 8 bits aglomerados (<code>B</code> mayúscula).</em></p><h3 id="_1-2-el-engano-de-la-letra-b-bits-vs-bytes" tabindex="-1">1.2 El Engaño de la Letra &quot;B&quot; (Bits vs Bytes) <a class="header-anchor" href="#_1-2-el-engano-de-la-letra-b-bits-vs-bytes" aria-label="Permalink to &quot;1.2 El Engaño de la Letra &quot;B&quot; (Bits vs Bytes)&quot;">​</a></h3><p>Cuando pagas un plan de internet de &quot;100 Megas&quot;, la compañía te está vendiendo <strong>100 Megabits por segundo (Mbps)</strong>. No te están vendiendo Megabytes. Si vas a descargar un archivo pesado (como una película que pesa 100 Megabytes, <code>MB</code>), tu cerebro piensa &quot;Si tengo 100 Megas de velocidad, bajará en 1 segundo&quot;. ¡Falso!</p><p>Como 1 Byte = 8 bits, para calcular tu velocidad real de descarga (Tasa de Transferencia Real / Throughput), debes dividir tu plan de internet entre 8:</p><ul><li>Plan de 100 Mbps / 8 = <strong>12.5 MB/s de descarga real máxima</strong>. La película de 100 MB tardará al menos 8 segundos en bajar.</li></ul><h3 id="_1-3-latencia-ping" tabindex="-1">1.3 Latencia (Ping) <a class="header-anchor" href="#_1-3-latencia-ping" aria-label="Permalink to &quot;1.3 Latencia (Ping)&quot;">​</a></h3><p>Es el tiempo que tarda un solo paquete en viajar desde tu PC hasta el servidor y volver. Se mide en milisegundos (ms). Puedes tener una tubería gigantesca de 1 Gigabit por segundo (Ancho de Banda extremo), pero si la latencia es alta (ej. 300 ms, como el internet satelital en días lluviosos), las videollamadas se cortarán y los videojuegos tendrán un retraso (Lag) insufrible, aunque la &quot;velocidad&quot; sea muy alta.</p><hr><h2 id="🧩-capitulo-ii-la-victoria-de-ethernet-tecnologias-lan" tabindex="-1">🧩 CAPÍTULO II: La Victoria de Ethernet (Tecnologías LAN) <a class="header-anchor" href="#🧩-capitulo-ii-la-victoria-de-ethernet-tecnologias-lan" aria-label="Permalink to &quot;🧩 CAPÍTULO II: La Victoria de Ethernet (Tecnologías LAN)&quot;">​</a></h2><p>En los años 80, no existía un estándar universal para redes LAN. Tres gigantes competían por el control del mercado: Token Ring (de IBM), FDDI (Fibra) y Ethernet (creada en Xerox PARC).</p><h3 id="_2-1-la-caida-de-los-rivales" tabindex="-1">2.1 La Caída de los Rivales <a class="header-anchor" href="#_2-1-la-caida-de-los-rivales" aria-label="Permalink to &quot;2.1 La Caída de los Rivales&quot;">​</a></h3><ul><li><strong>Token Ring (Topología de Anillo Lógico):</strong> Funcionaba enviando un &quot;Testigo&quot; electrónico circulando por la red. Si una PC quería hablar, agarraba el testigo. Era muy ordenado y no había colisiones, pero el cable era muy costoso y el mantenimiento complejo.</li><li><strong>FDDI:</strong> Usaba anillos dobles de fibra óptica hiperrápidos. Pero en los años 90, instalar tarjetas de fibra óptica en las computadoras de una oficina normal era económicamente inviable.</li></ul><h3 id="_2-2-por-que-gano-ethernet" tabindex="-1">2.2 Por qué ganó Ethernet <a class="header-anchor" href="#_2-2-por-que-gano-ethernet" aria-label="Permalink to &quot;2.2 Por qué ganó Ethernet&quot;">​</a></h3><p>Ethernet ganó por ser <strong>Barato, Simple y Tolerante al Caos</strong>. Ethernet utiliza un protocolo llamado <strong>CSMA/CD (Acceso Múltiple por Detección de Portadora y Detección de Colisiones)</strong>. Su filosofía era como un grupo de personas en una habitación a oscuras intentando hablar:</p><ol><li>Escucho (CS): ¿Hay alguien hablando por el cable?</li><li>Si hay silencio, hablo (Transmito).</li><li>Detección (CD): Si da la casualidad que otra persona habló en el mismo milisegundo que yo, los mensajes chocan (Colisión). Ambas PCs detectan el choque, se callan, esperan un tiempo matemático aleatorio microscópico, y vuelven a intentar.</li></ol><p>Con la evolución y masificación de los <strong>Switches</strong> (que eliminaron por completo las colisiones), Ethernet abandonó CSMA/CD, pero mantuvo su formato de &quot;Tramas&quot; baratas. Hoy en día, casi el 100% de las redes LAN del planeta cableadas con RJ45 son redes Ethernet.</p><h3 id="_2-3-estandares-de-velocidad-ethernet" tabindex="-1">2.3 Estándares de Velocidad Ethernet <a class="header-anchor" href="#_2-3-estandares-de-velocidad-ethernet" aria-label="Permalink to &quot;2.3 Estándares de Velocidad Ethernet&quot;">​</a></h3><ul><li>Standard Ethernet (10 Mbps) - Obsoleto.</li><li>Fast Ethernet (100 Mbps) - Estándar base de oficinas antiguas.</li><li><strong>Gigabit Ethernet (1000 Mbps / 1 Gbps)</strong> - El estándar dominante moderno.</li><li>10 Gigabit Ethernet - Usado en servidores y Data Centers.</li></ul><hr><h2 id="💻-resumen-del-trimestre-i" tabindex="-1">💻 Resumen del Trimestre I <a class="header-anchor" href="#💻-resumen-del-trimestre-i" aria-label="Permalink to &quot;💻 Resumen del Trimestre I&quot;">​</a></h2><p>Has completado el cimiento físico y lógico fundacional. Has aprendido:</p><ol><li>Con qué cables físicos transmitir (Cobre, Fibra, Aire).</li><li>Cómo organizar la arquitectura geométrica para que la red no colapse (Topología en Estrella con Switches).</li><li>Cómo el software mundial se pone de acuerdo para hablar un mismo idioma independientemente del fabricante (Modelo OSI).</li><li>La medición de las carreteras digitales y por qué Ethernet gobierna el hardware local.</li></ol><p>El próximo trimestre pasaremos a dominar la Capa 3: asignaremos Direcciones IP lógicas a las computadoras, construiremos Subredes y levantaremos cortafuegos de seguridad para defender el perímetro.</p><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Ancho de Banda (Bandwidth):</strong> Medida física teórica que cuantifica la capacidad máxima de un canal de comunicación para transferir datos en un lapso específico, expresada normativamente en bits por segundo (bps).</li><li><strong>Tasa de Transferencia (Throughput):</strong> Métrica de rendimiento empírico que determina el volumen de datos útiles efectivamente transmitidos y recibidos de forma exitosa por unidad de tiempo, usualmente menor al Ancho de Banda bruto debido a los márgenes de encapsulamiento y colisiones.</li><li><strong>Latencia (Latency):</strong> Retardo cronológico asociado a la propagación temporal de una señal o paquete de datos a través del medio de transmisión desde su punto de origen hasta su punto de recepción.</li><li><strong>Ethernet (IEEE 802.3):</strong> Estándar tecnológico de facto para redes de área local (LAN) caracterizado por su esquema de encapsulamiento en tramas de Capa 2 y, en sus arquitecturas legadas (Half-duplex), regulado por protocolos de acceso estocástico CSMA/CD.</li><li><strong>CSMA/CD (Carrier-Sense Multiple Access with Collision Detection):</strong> Protocolo determinista de control de acceso al medio utilizado en arquitecturas de topología bus compartida. Estipula directivas algorítmicas de &quot;escucha antes de transmitir&quot; y resolución matemática de retrasos tras la detección de una coalición eléctrica de señales (colisión).</li></ul>',37)])])}const h=e(i,[["render",r]]);export{p as __pageData,h as default};
